import json
import numpy as np

# Truth vectors use lexicographic tuples with input 0 as the most significant bit.
N = 1024
xs = np.array([[(i >> (9-j)) & 1 for j in range(10)] for i in range(N)], dtype=np.uint8)
W0 = W

def get(name):
    return np.asarray(W0["target." + name])

# Each hidden neuron is decoded as a Boolean threshold gate over its incoming
# Boolean signals. Its local truth table is converted to AND/OR/NOT logic;
# those Boolean expressions are then evaluated on the input domain.
h = [xs[:, j].astype(bool) for j in range(10)]
for layer in range(4):
    mat = get(f"w{layer}")
    bias = get(f"b{layer}")
    nxt = []
    for row in range(34):
        parents = np.flatnonzero(mat[row])
        if not len(parents):
            nxt.append(np.full(N, bias[row] > 0, dtype=bool))
            continue
        terms = []
        for mask in range(1 << len(parents)):
            z = float(bias[row])
            for k, p in enumerate(parents):
                z += float(mat[row, p]) * ((mask >> k) & 1)
            if z <= 0:
                continue
            lits = [
                h[p] if ((mask >> k) & 1) else ~h[p]
                for k, p in enumerate(parents)
            ]
            term = lits[0].copy()
            for lit in lits[1:]:
                term &= lit
            terms.append(term)
        if not terms:
            nxt.append(np.zeros(N, dtype=bool))
        else:
            value = terms[0].copy()
            for term in terms[1:]:
                value |= term
            nxt.append(value)
    h = nxt

# The output head encodes q = h[10] + h[11] - h[12] as the class-1
# indicator (the other two logits make class 0 the alternative).
q = h[10].astype(int) + h[11].astype(int) - h[12].astype(int)
outputs = (q > 0).astype(int).tolist()
